/*
 * Figure 80: trimmed faces, generated by PARAMETRIC and RESTRICTED_DELAUNAY.
 *   - a square plate with a round hole and the disk filling it (another
 *     plane's parametrization; the circle their shared edge): the faces
 *     coloured, their triangles meeting along the circle;
 *   - an L-shaped plate with three round holes (its trims ear-clipped,
 *     remeshed in its metric) by RESTRICTED_DELAUNAY: every angle at least
 *     30 degrees;
 *   - an annular sector (four trim pieces) by STRUCTURED: its grid the Coons
 *     map of its sides, quads following the arcs.
 */

static qaws_curve* ms_tr_line(double x0, double y0, double x1, double y1)
{
	qaws_bezier_desc bd;
	qaws_scalar cp[4];
	qaws_curve* c = NULL;
	cp[0] = (qaws_scalar)x0; cp[1] = (qaws_scalar)y0; cp[2] = (qaws_scalar)x1; cp[3] = (qaws_scalar)y1;
	memset(&bd, 0, sizeof bd);
	bd.dimension = QAWS_DIMENSION_2D; bd.degree = 1; bd.control_points = cp; bd.control_point_count = 2;
	qaws_curve_create_bezier(&c, &bd);
	return c;
}

static qaws_curve* ms_tr_arc(double cx, double cy, double r, double a0, double a1)
{
	qaws_arc_segment g;
	qaws_arc_desc ad;
	qaws_curve* c = NULL;
	memset(&g, 0, sizeof g);
	g.center[0] = (qaws_scalar)cx; g.center[1] = (qaws_scalar)cy; g.radius = (qaws_scalar)r;
	g.angle_start = (qaws_scalar)a0; g.angle_end = (qaws_scalar)a1;
	memset(&ad, 0, sizeof ad);
	ad.dimension = QAWS_DIMENSION_2D; ad.segments = &g; ad.segment_count = 1;
	qaws_curve_create_arc(&c, &ad);
	return c;
}

static qaws_surface* ms_tr_plane(double const (*P)[3])
{
	qaws_surface_bilinear_desc d;
	qaws_surface* s = NULL;
	memset(&d, 0, sizeof d);
	d.p00.x = (qaws_scalar)P[0][0]; d.p00.y = (qaws_scalar)P[0][1]; d.p00.z = (qaws_scalar)P[0][2];
	d.p10.x = (qaws_scalar)P[1][0]; d.p10.y = (qaws_scalar)P[1][1]; d.p10.z = (qaws_scalar)P[1][2];
	d.p01.x = (qaws_scalar)P[2][0]; d.p01.y = (qaws_scalar)P[2][1]; d.p01.z = (qaws_scalar)P[2][2];
	d.p11.x = (qaws_scalar)P[3][0]; d.p11.y = (qaws_scalar)P[3][1]; d.p11.z = (qaws_scalar)P[3][2];
	qaws_surface_create_bilinear(&s, &d);
	return s;
}

/* a generated shell's faces drawn in their faces' colours */
static void ms_tr_draw(er_canvas* c, qaws_mesh_3d const* g, double const (*pal)[3], double const* wire)
{
	unsigned int nf = qaws_mesh_3d_get_face_count(g), f, a, q = 0, k;
	qaws_scalar* fid = (qaws_scalar*)malloc(sizeof(qaws_scalar) * nf);
	unsigned int* fs = (unsigned int*)malloc(sizeof(unsigned int) * nf);
	unsigned int* fv = (unsigned int*)malloc(sizeof(unsigned int) * qaws_mesh_3d_get_corner_count(g));
	double* p = ms_positions(g);
	qaws_mesh_3d_find_attribute(&a, g, "face");
	qaws_mesh_3d_get_attribute(fid, g, a);
	qaws_mesh_3d_get_faces(fv, fs, g);
	for (f = 0; f < nf; f++)
	{
		unsigned int id = (unsigned int)fid[f] % 6;
		for (k = 1; k + 1 < fs[f]; k++)
			er_triangle(c, p + 3 * fv[q], p + 3 * fv[q + k], p + 3 * fv[q + k + 1], NULL, NULL, NULL, pal[id], pal[id], pal[id]);
		q += fs[f];
	}
	ms_draw(c, g, NULL, NULL, 0, wire, 1.0);
	free(fid); free(fs); free(fv); free(p);
}

static void demo_generate_trimmed(void)
{
	static double const wire[3] = { 40, 45, 60 };
	static double const pal[6][3] = { { 178, 192, 212 }, { 232, 196, 120 }, { 170, 205, 160 }, { 205, 185, 220 }, { 120, 198, 121 }, { 49, 130, 189 } };
	static double const A[4][3] = { { -2, -2, 0 }, { 2, -2, 0 }, { -2, 2, 0 }, { 2, 2, 0 } }, B[4][3] = { { 1, -1, 0 }, { 1, 1, 0 }, { -1, -1, 0 }, { -1, 1, 0 } };
	er_canvas* c = er_create(2100, 700, 3, 252, 252, 250);
	qaws_surface *sa = ms_tr_plane(A), *sb = ms_tr_plane(B), *sl = ms_tr_plane(A);
	qaws_curve *oc[4], *hole, *disk, *lc[6], *holes[3];
	qaws_curve const *ol[4], *hl[1], *dl[1], *ll[6], *hh[3][1];
	qaws_path_2d pa[2], pb[1], pl[4];
	qaws_shell_face_desc fd[2], fl[1];
	qaws_shell_atlas *a = NULL, *al = NULL;
	qaws_generate_desc d;
	qaws_mesh_report rep;
	qaws_mesh_3d* g = NULL;
	char sub[200];
	unsigned int i;
	if (!c || !sa || !sb || !sl)
		return;
	oc[0] = ms_tr_line(0.125, 0.125, 0.875, 0.125);
	oc[1] = ms_tr_line(0.875, 0.125, 0.875, 0.875);
	oc[2] = ms_tr_line(0.875, 0.875, 0.125, 0.875);
	oc[3] = ms_tr_line(0.125, 0.875, 0.125, 0.125);
	hole = ms_tr_arc(0.5, 0.5, 0.2, 0, 2 * MS_PI);
	disk = ms_tr_arc(0.5, 0.5, 0.4, 1.0, 1.0 + 2 * MS_PI);
	for (i = 0; i < 4; i++)
		ol[i] = oc[i];
	hl[0] = hole;
	dl[0] = disk;
	pa[0].curves = ol; pa[0].curve_count = 4; pa[0].closed = 1;
	pa[1].curves = hl; pa[1].curve_count = 1; pa[1].closed = 1;
	pb[0].curves = dl; pb[0].curve_count = 1; pb[0].closed = 1;
	fd[0].surface = sa; fd[0].trims = pa; fd[0].trim_count = 2;
	fd[1].surface = sb; fd[1].trims = pb; fd[1].trim_count = 1;
	qaws_shell_atlas_create_trimmed(&a, fd, 2, 0);
	memset(&d, 0, sizeof d);
	d.method = QAWS_GENERATE_PARAMETRIC;
	d.target_length = (qaws_scalar)0.2;
	if (a && qaws_mesh_generate_shell(&g, &rep, a, &d) == QAWS_STATUS_OK && g)
	{
		sprintf(sub, "%u triangles, angles %.0f..%.0f", qaws_mesh_3d_get_face_count(g), (double)rep.quality.min_angle, (double)rep.quality.max_angle);
		ms_panel(c, 0, 0, 700, 700, g, 0.3, 0.9, "a plate's hole and its disk", sub);
		ms_tr_draw(c, g, pal, wire);
		printf("  plate and disk: %u triangles, angles %.1f..%.1f\n", qaws_mesh_3d_get_face_count(g), (double)rep.quality.min_angle, (double)rep.quality.max_angle);
	}
	qaws_mesh_3d_destroy(g);
	g = NULL;
	/* the L: (0.1, 0.1) to (0.9, 0.1) to (0.9, 0.5) to (0.5, 0.5) to (0.5, 0.9) to (0.1, 0.9); three holes */
	lc[0] = ms_tr_line(0.1, 0.1, 0.9, 0.1);
	lc[1] = ms_tr_line(0.9, 0.1, 0.9, 0.5);
	lc[2] = ms_tr_line(0.9, 0.5, 0.5, 0.5);
	lc[3] = ms_tr_line(0.5, 0.5, 0.5, 0.9);
	lc[4] = ms_tr_line(0.5, 0.9, 0.1, 0.9);
	lc[5] = ms_tr_line(0.1, 0.9, 0.1, 0.1);
	holes[0] = ms_tr_arc(0.3, 0.3, 0.1, 0, 2 * MS_PI);
	holes[1] = ms_tr_arc(0.7, 0.3, 0.08, 0, 2 * MS_PI);
	holes[2] = ms_tr_arc(0.3, 0.7, 0.08, 0, 2 * MS_PI);
	for (i = 0; i < 6; i++)
		ll[i] = lc[i];
	pl[0].curves = ll; pl[0].curve_count = 6; pl[0].closed = 1;
	for (i = 0; i < 3; i++)
	{
		hh[i][0] = holes[i];
		pl[1 + i].curves = hh[i]; pl[1 + i].curve_count = 1; pl[1 + i].closed = 1;
	}
	fl[0].surface = sl; fl[0].trims = pl; fl[0].trim_count = 4;
	qaws_shell_atlas_create_trimmed(&al, fl, 1, 0);
	d.method = QAWS_GENERATE_RESTRICTED_DELAUNAY;
	d.target_length = (qaws_scalar)0.12;
	if (al && qaws_mesh_generate_shell(&g, &rep, al, &d) == QAWS_STATUS_OK && g)
	{
		sprintf(sub, "%u triangles, angles %.1f..%.1f", qaws_mesh_3d_get_face_count(g), (double)rep.quality.min_angle, (double)rep.quality.max_angle);
		ms_panel(c, 700, 0, 700, 700, g, 0.3, 0.9, "RESTRICTED_DELAUNAY, an L, 3 holes", sub);
		ms_tr_draw(c, g, pal, wire);
		printf("  L with holes: %u triangles, angles %.1f..%.1f\n", qaws_mesh_3d_get_face_count(g), (double)rep.quality.min_angle, (double)rep.quality.max_angle);
	}
	else
		printf("  L with holes failed\n");
	qaws_mesh_3d_destroy(g);
	{
		qaws_curve *sc[4];
		qaws_curve const* sl[4];
		qaws_path_2d ps[1];
		qaws_shell_face_desc fs1[1];
		qaws_shell_atlas* as = NULL;
		double hp = 0.5 * MS_PI;
		sc[0] = ms_tr_line(0.6, 0.5, 0.85, 0.5);
		sc[1] = ms_tr_arc(0.5, 0.5, 0.35, 0, hp);
		sc[2] = ms_tr_line(0.5, 0.85, 0.5, 0.6);
		sc[3] = ms_tr_arc(0.5, 0.5, 0.1, hp, 0);
		for (i = 0; i < 4; i++)
			sl[i] = sc[i];
		ps[0].curves = sl; ps[0].curve_count = 4; ps[0].closed = 1;
		fs1[0].surface = sa; fs1[0].trims = ps; fs1[0].trim_count = 1;
		qaws_shell_atlas_create_trimmed(&as, fs1, 1, 0);
		d.method = QAWS_GENERATE_STRUCTURED;
		d.elements = QAWS_ELEMENTS_QUADS;
		d.target_length = (qaws_scalar)0.1;
		g = NULL;
		if (as && qaws_mesh_generate_shell(&g, &rep, as, &d) == QAWS_STATUS_OK && g)
		{
			sprintf(sub, "%u quads, %u irregular", rep.quality.quads, rep.quality.irregular);
			ms_panel(c, 1400, 0, 700, 700, g, 0.3, 0.9, "STRUCTURED, an annular sector", sub);
			ms_tr_draw(c, g, pal + 2, wire);
			printf("  annular sector: %u quads, %u irregular\n", rep.quality.quads, rep.quality.irregular);
		}
		qaws_mesh_3d_destroy(g);
		qaws_shell_atlas_destroy(as);
		for (i = 0; i < 4; i++)
			qaws_curve_destroy(sc[i]);
	}
	er_save(c, "showcase/mesh80_generate_trimmed.png");
	printf("mesh80_generate_trimmed.png\n");
	qaws_shell_atlas_destroy(a);
	qaws_shell_atlas_destroy(al);
	for (i = 0; i < 4; i++)
		qaws_curve_destroy(oc[i]);
	for (i = 0; i < 6; i++)
		qaws_curve_destroy(lc[i]);
	for (i = 0; i < 3; i++)
		qaws_curve_destroy(holes[i]);
	qaws_curve_destroy(hole);
	qaws_curve_destroy(disk);
	qaws_surface_destroy(sa);
	qaws_surface_destroy(sb);
	qaws_surface_destroy(sl);
	er_destroy(c);
}
